export const PENTHOUSE_LOT_DATA_URI = "data:image/jpeg;base64,";
export const PENTHOUSE_LOT_WIDTH = 500;
export const PENTHOUSE_LOT_HEIGHT = 686;

// The gate is made fully visible right at the sidewalk, like
// Mansion/Suburban — its own crossing (a plain asphalt strip, like
// Trailer/Apartment's) reaches exactly as far as the sidewalk's
// original (pre-narrowing) depth by default, so 234px of the photo's own
// clean grass (sampled from the building-free band between the hedge and
// the gate, tiled) is padded onto the top before resizing to width 500 —
// enough to push the gate's own arch, lamps and bars just past that
// reach, with no separate extraDepth tuning needed on the crossing
// itself (see street.ts). Earlier passes got this wrong from both ends:
// too little padding left the gate hidden behind the sidewalk's masking
// zone with nothing to show for it, and a too-short crossing (extraDepth
// trimmed to match the *narrowed* sidewalk's shallower visible band)
// stopped short of the gate too, leaving a visible grass gap either way.
// Also doubles as the GROUND_STRIP fallback tile below (repeat-tiled
// downward on the rare screen tall enough that the box's depth exceeds
// the photo at its natural scale) since it's already a clean, seamless
// strip by construction.
export const PENTHOUSE_LOT_GROUND_STRIP_TOP = 5;
export const PENTHOUSE_LOT_GROUND_STRIP_HEIGHT = 10;

// Brightened to match the Mansion's lighter, more vivid look — same
// gamma-lift (x1.12 brightness, gamma 0.85) and mild re-saturation
// (x1.05) as townhouseLot.ts, applied on top of the gate-visibility
// padding above (pure color grade, no resize/crop, so WIDTH/HEIGHT and
// the ground-strip constants are unchanged).

// A row of flowering boxwood bushes (from a separate reference photo,
// not the main source) is pasted directly onto the near-road strip right
// where the sidewalk's masking zone ends (rows 85-115 of this 500-wide
// image — the narrow band between the visible-boundary math above and
// where the gate's own arch begins) — the user found the plain grass
// there too bare next to the Mansion/Suburban's planted fences. Tiled
// (~4x) and dimmed slightly (x0.95) to blend with the rest of the scene.
// Placed at exactly this row range deliberately: any shallower and the
// generic sidewalk band painted over it; any deeper and it would collide
// with the gate's own arch/lamps.
